package com.hbm.entity.mob.maskman;
import com.hbm.armor.ArmorModStorage;import com.hbm.interfaces.IArmorModDash;import com.hbm.registry.HbmSounds;import java.util.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ArmorItem;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.neoforge.event.tick.PlayerTickEvent;
/** Original EntityEffectHandler.handleDashing: transient stamina/cooldown, source cap/recharge and additive horizontal momentum. */
public final class CloudDashRuntime {
 public static final class State{public int count,stamina,cooldown;public boolean pressed;}
 private static final Map<Player,State> DATA=Collections.synchronizedMap(new WeakHashMap<>());private static final ResourceLocation SPEED=ResourceLocation.parse("hbm:1d11e63e-28c4-4e14-b09f-fe0bd1be708f");
 public static State state(Player player){return DATA.computeIfAbsent(player,p->new State());}
 public static int dashes(Player player){int total=0;
  var chest=player.getItemBySlot(EquipmentSlot.CHEST);
  if(com.hbm.armor.t51.T51Runtime.fullSet(player,true)&&chest.getItem() instanceof com.hbm.weapon.sedna.gun.GunArmorPerks.FullSetArmor fullSet)total+=fullSet.fsbDashCount();
  for(var slot:new EquipmentSlot[]{EquipmentSlot.FEET,EquipmentSlot.LEGS,EquipmentSlot.CHEST,EquipmentSlot.HEAD}){var armor=player.getItemBySlot(slot);if(armor.getItem() instanceof ArmorItem&&ArmorModStorage.hasMods(armor))for(int i=0;i<8;i++){var mod=ArmorModStorage.pryMod(armor,i,player.registryAccess());if(mod.getItem() instanceof IArmorModDash dash)total+=dash.getDashes();}}return total;}
 @SubscribeEvent public static void speed(net.neoforged.neoforge.event.tick.EntityTickEvent.Pre event){if(!(event.getEntity() instanceof net.minecraft.world.entity.LivingEntity living))return;var speed=living.getAttribute(Attributes.MOVEMENT_SPEED);if(speed!=null){boolean cloud=false;for(var armor:living.getArmorSlots())if(ArmorModStorage.hasMods(armor))for(var mod:ArmorModStorage.pryMods(armor,living.registryAccess()))if(mod.getItem() instanceof BottledCloudItem)cloud=true;var existing=speed.getModifier(SPEED);if(cloud&&existing==null)speed.addTransientModifier(new AttributeModifier(SPEED,.125,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));else if(!cloud&&existing!=null)speed.removeModifier(SPEED);}}
 @SubscribeEvent public static void tick(PlayerTickEvent.Pre event){var player=event.getEntity();var data=state(player);data.count=dashes(player);if(data.count*30<data.stamina)data.stamina=data.count*30;if(data.count>0){int stamina=data.stamina;if(data.cooldown<=0){if(data.pressed&&stamina>=30){var look=player.getLookAngle();var strafe=look.yRot((float)Math.PI*.5F);int forward=(int)Math.signum(player.zza),side=(int)Math.signum(player.xxa);if(forward==0&&side==0)forward=1;player.setDeltaMovement(player.getDeltaMovement().add(look.x*forward+strafe.x*side,0,look.z*forward+strafe.z*side).multiply(1,0,1));player.fallDistance=0;player.hurtMarked=true;player.playSound(HbmSounds.get("weapon.rocketFlame"),1,1);data.cooldown=5;stamina-=30;}}else{data.cooldown--;data.pressed=false;}if(stamina<data.count*30){stamina++;if(stamina%30==29){player.playSound(HbmSounds.get("item.techBoop"),1,1+(1F/12F)*(stamina/30));stamina++;}}data.stamina=stamina;}}
 /** Original ModEventHandler.onPlayerChangeDimension clears the DASH key, but not stamina/cooldown. */
 @SubscribeEvent public static void dimension(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerChangedDimensionEvent event){state(event.getEntity()).pressed=false;}
 private CloudDashRuntime(){}
}
